<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>Case Reporting 201: Salesforce Case Management Training</title>
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <style>
    /* --- Base / layout --- */
    * { box-sizing: border-box; }
    html, body {
      margin: 0;
      padding: 0;
      width: 900px;           /* requested screenshot size */
      height: 558px;          /* requested screenshot size */
      overflow: hidden;       /* avoid scrollbars in the capture */
      background: #eef3f7;
      color: #1f2a33;
      font: 14px/1.45 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }
    .app {
      display: flex;
      flex-direction: column;
      height: 100%;
      width: 100%;
      border: 1px solid #d7e1ea;
      background: #fff;
      box-shadow: 0 6px 24px rgba(18, 35, 58, 0.08);
      border-radius: 10px;
      overflow: hidden;
    }

    /* --- Header / chrome --- */
    .app-header {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 12px;
      align-items: center;
      padding: 10px 16px;
      background: linear-gradient(90deg,#0b5cab 0%, #0176d3 70%, #1b96ff 100%);
      color: #fff;
    }
    .brand {
      display: flex;
      align-items: center;
      gap: 10px;
      min-width: 0;
    }
    .cloud {
      position: relative;
      width: 28px;
      height: 18px;
      background: #fff;
      border-radius: 16px;
      box-shadow: 0 0 0 1px rgba(0,0,0,.05) inset;
    }
    .cloud:before, .cloud:after {
      content: "";
      position: absolute;
      background: #fff;
      border-radius: 50%;
    }
    .cloud:before { width: 12px; height: 12px; left: -6px; top: 3px; }
    .cloud:after  { width: 14px; height: 14px; right: -7px; top: 1px; }
    .brand-title {
      display: flex;
      flex-direction: column;
      line-height: 1.2;
    }
    .brand-title strong { font-size: 15px; letter-spacing: .2px; }
    .brand-title span { font-size: 12px; opacity: .9; }
    .meta {
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 12px;
      opacity: .95;
    }
    .pill {
      padding: 3px 15px 15px 15px;
      background: rgba(255,255,255,.15);
      border: 1px solid rgba(255,255,255,.35);
      border-radius: 999px;
      backdrop-filter: blur(2px);
      white-space: nowrap;
    }
    .crumbs {
      display: flex;
      gap: 8px;
      align-items: center;
      font-size: 12px;
      margin-top: 4px;
      opacity: .95;
    }
    .crumbs .sep { opacity: .8; }
    .crumbs .current { font-weight: 600; }

    /* --- Content area --- */
    .content {
      display: grid;
      grid-template-columns: 240px 1fr;
      gap: 0;
      flex: 1;
      min-height: 0;
      background: #f7f9fc;
    }
    aside.outline {
      background: #fff;
      border-right: 1px solid #e6edf3;
      display: flex;
      flex-direction: column;
      padding: 12px 12px 10px 12px;
    }
    .outline h3 {
      margin: 6px 0 10px;
      font-size: 12px;
      text-transform: uppercase;
      letter-spacing: .08em;
      color: #5a6b7b;
    }
    .outline .item {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 8px 8px;
      margin-bottom: 4px;
      border-radius: 8px;
      color: #1f2a33;
    }
    .outline .item .dot {
      width: 8px; height: 8px; border-radius: 50%;
      background: #ccd9e6;
      box-shadow: 0 0 0 2px #eef3f7 inset;
    }
    .outline .item.active {
      background: #edf5ff;
      font-weight: 600;
      color: #0b5cab;
    }
    .outline .item.active .dot { background: #1b96ff; box-shadow: 0 0 0 2px #d7ebff inset; }
    .outline .muted { color: #6c7d8c; }
    .outline .spacer { flex: 1; }
    .outline .legend {
      display: flex; justify-content: space-between; align-items: center;
      font-size: 11px; color: #6c7d8c; padding-top: 6px; border-top: 1px dashed #e6edf3;
    }

    main.slide {
      background: #ffffff;
      padding: 18px 24px 10px 24px;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      min-width: 0;
    }
    .slidehead {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      margin-bottom: 6px;
    }
    .slidehead .title {
      font-size: 22px;
      margin: 0;
      letter-spacing: .2px;
      line-height: 1.3;
    }
    .badge {
      font-size: 11px;
      padding: 4px 8px;
      border-radius: 999px;
      background: #f0f4f8;
      color: #3a4a59;
      border: 1px solid #e3ebf3;
    }

    .setup-box {
      margin: 10px 0 14px;
      padding: 10px 12px;
      border-left: 4px solid #f0b429;
      background: #fff7e0;
      border-radius: 8px;
      color: #5a4a1b;
      box-shadow: 0 1px 0 rgba(0,0,0,.02) inset;
    }
    .setup-box strong { color: #7a5a00; }
    .setup-box .hint { 
      font-size: 11px; 
      color: #8a7a5a;
      margin-top: 6px;
      line-height: 1.4;
    }

    h2 {
      margin: 12px 0 8px;
      font-size: 16px;
      color: #0b5cab;
    }
    ul { margin: 0 0 8px 16px; padding: 0; }
    li { margin: 6px 0; }
    em { color: #5a6b7b; }

    /* --- Footer controls --- */
    .footer {
      display: grid;
      grid-template-columns: 1fr auto;
      align-items: center;
      gap: 12px;
      padding: 10px 14px;
      background: #fbfcfe;
      border-top: 1px solid #e6edf3;
    }
    .progress {
      display: grid;
      grid-template-columns: auto 1fr auto;
      align-items: center;
      gap: 10px;
      font-size: 12px;
      color: #425a70;
    }
    .progressbar {
      height: 8px;
      background: #e9f1f9;
      border-radius: 999px;
      overflow: hidden;
      box-shadow: inset 0 0 0 1px #d9e6f2;
      min-width: 280px;
    }
    .progressbar .bar {
      height: 100%;
      width: 4.2%; /* Slide 1 of 24 ≈ 4.17% */
      background: linear-gradient(90deg,#1b96ff,#0b5cab);
      border-radius: 999px;
    }
    .controls {
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      appearance: none;
      border: 1px solid #cfd8e3;
      background: #fff;
      padding: 0px 12px 14px 12px;
      height: 30px;
      border-radius: 8px;
      font-weight: 600;
      font-size: 13px;
      color: #183247;
      cursor: default;
      box-shadow: 0 1px 0 rgba(18,35,58,0.05);
      user-select: none;
    }
    .btn.primary {
      background: #0176d3;
      border-color: #0160aa;
      color: #fff;
      cursor: pointer;
    }
    .btn:disabled {
      opacity: .5;
    }
    .footer small {
      color: #6c7d8c;
      font-size: 11px;
    }

    /* --- Minor helpers --- */
    .kpis {
      display: inline-flex; 
      gap: 8px; 
      align-items: center;
      margin-left: 8px;
      margin-top: 3px;
    }
    .kpi {
      display: inline-flex;
      align-items: center;
      font-size: 11px; 
      padding: 0px 8px 12px 8px; 
      height: 34px;
      border-radius: 6px;
      background: #eaf4ff; 
      color: #0b5cab; 
      border: 1px solid #d7ebff;
      white-space: nowrap;
    }
    .muted { color: #6c7d8c; }
    .sep { opacity: .5; }
    .note { margin-top: 6px; font-size: 12px; color: #5a6b7b; }
    .flex { display: flex; align-items: center; gap: 8px; }
  </style>
</head>

